import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
import {DRACOLoader} from 'three/addons/loaders/DRACOLoader.js';
import {displayName,cleanName,sideOf,topicFor,searchText,normalize,sourceURL} from './content.js';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const layerDefs=[{id:'skeleton',name:'Kemikler',sub:'İskelet sistemi',icon:'◇',color:'#d5c7a5'},{id:'muscular',name:'Kaslar',sub:'Kas sistemi',icon:'≋',color:'#bd7263'},{id:'visceral',name:'Organlar',sub:'İç organlar',icon:'◉',color:'#ad8096'},{id:'cardiovascular',name:'Damarlar & kalp',sub:'Dolaşım sistemi',icon:'♡',color:'#ba6471'},{id:'nervous',name:'Sinirler',sub:'Sinir sistemi ve duyu organları',icon:'⌁',color:'#b8a456'},{id:'tendons',name:'Tendonlar',sub:'Kas modelindeki tendon yapıları',icon:'⋈',color:'#b6b79a'}];
const active=new Set(['skeleton','muscular']);const objects=new Map(),hidden=new Set(),loaded=new Map(),inflight=new Map();let catalog=[],selected=null,isolated=false,alpha=1,explosion=0,renderer,scene,camera,controls,raf=0,ready=false,toastTimer;const mount=$('#canvasMount');
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function layerName(id){return layerDefs.find(d=>d.id===id)?.name||id;}
function renderLayers(){ $('#layers').innerHTML=layerDefs.map(d=>`<button class="layer ${active.has(d.id)?'active':''}" data-layer="${d.id}" aria-pressed="${active.has(d.id)}"><span class="layer-icon" style="--color:${d.color}">${d.icon}</span><span><b>${d.name}</b><small>${d.sub}</small></span><span class="switch" aria-hidden="true"></span></button>`).join('');$('#allLayers').textContent=active.size===6?'Tümünü kapat':'Tümünü aç'; }
function visible(o){return (isolated?o===selected:active.has(o.userData.record.layer))&&!hidden.has(o.userData.record.id);}
function refresh(){let count=0;for(const o of objects.values()){o.visible=visible(o);if(o.visible)count++;const m=o.material;m.opacity=o===selected?1:alpha;m.transparent=m.opacity<1;m.depthWrite=!m.transparent;m.emissive.set(o===selected?0x77bb83:0x000000);m.emissiveIntensity=o===selected?.45:0;const base=o.userData.basePosition;const dir=o.userData.explodeDirection;o.position.copy(base).addScaledVector(dir,explosion*.35); }$('#meshCount').textContent=`${count.toLocaleString('tr-TR')} görünür parça`;$('#isolate')?.setAttribute('aria-pressed',String(isolated));if($('#isolate'))$('#isolate').textContent=isolated?'Bütüne dön':'Tek başına';requestRender();}
function requestRender(){if(!raf&&renderer)raf=requestAnimationFrame(render);}
function render(){raf=0;controls.update();renderer.render(scene,camera);}
async function loadLayer(id){const file=id==='tendons'?'muscular':id;if(loaded.has(file))return;if(inflight.has(file))return inflight.get(file);const job=(async()=>{const loader=new GLTFLoader();const draco=new DRACOLoader();draco.setDecoderPath('./vendor/examples/jsm/libs/draco/gltf/');draco.setWorkerLimit(2);loader.setDRACOLoader(draco);try{const gltf=await loader.loadAsync(`./models/${file}.glb`);gltf.scene.updateMatrixWorld(true);gltf.scene.traverse(o=>{if(!o.isMesh)return;const association=gltf.parser.associations.get(o);const node=association?.nodes;const record=catalog.find(r=>r.file===file&&r.node===node);if(!record){o.visible=false;return;}o.userData.record=record;const original=Array.isArray(o.material)?o.material[0]:o.material;o.material=original.clone();o.material.metalness=0;o.material.roughness=.62;o.material.side=THREE.DoubleSide;o.userData.basePosition=o.position.clone();const center=new THREE.Box3().setFromObject(o).getCenter(new THREE.Vector3());const dir=center.clone().sub(new THREE.Vector3(0,.9,0));dir.y*=.35;if(dir.length()<.001)dir.set(.1,0,.1);o.userData.explodeDirection=dir.normalize();objects.set(record.id,o);});scene.add(gltf.scene);loaded.set(file,gltf.scene);refresh();}finally{draco.dispose();}})();inflight.set(file,job);try{await job;}finally{inflight.delete(file);}}
async function toggleLayer(id){if(!layerDefs.some(d=>d.id===id))throw Error('Geçersiz katman');if(active.has(id)){active.delete(id);}else{active.add(id);try{await loadLayer(id);}catch(e){active.delete(id);toast('Katman yüklenemedi. Bağlantını kontrol edip tekrar dene.');console.error(e);}}isolated=false;renderLayers();refresh();}
function frameObject(o){const box=new THREE.Box3().setFromObject(o);const center=box.getCenter(new THREE.Vector3());const size=box.getSize(new THREE.Vector3()).length();const distance=Math.max(.15,size*1.5);const direction=camera.position.clone().sub(controls.target).normalize();controls.target.copy(center);camera.position.copy(center).addScaledVector(direction,distance);controls.update();requestRender();}
function choose(o,{focus=false,isolate=false}={}){selected=o;hidden.delete(o.userData.record.id);if(isolate)isolated=true;active.add(o.userData.record.layer);renderLayers();refresh();showDetails(o.userData.record);if(focus)frameObject(o);$('#selectionLabel').textContent=displayName(o.userData.record.name);$('#selectionLabel').hidden=false;$('#details').classList.add('open');$('#sidebar').classList.remove('open');}
function showDetails(r){const t=topicFor(r.name);const name=displayName(r.name);const parent=t&&normalize(cleanName(r.name))!==normalize(t.match);$('#detailContent').innerHTML=`<span class="detail-tag">${esc(layerName(r.layer))}${sideOf(r.name)?' · '+sideOf(r.name):''}</span><h2>${esc(name)}</h2><p class="english-name">${esc(cleanName(r.name))}</p><div class="detail-actions"><button id="focus">Yakınlaş ↗</button><button id="isolate" aria-pressed="${isolated}">${isolated?'Bütüne dön':'Tek başına'}</button><button id="hide">Gizle</button></div>${t?`${parent?`<div class="detail-block"><h3>İlgili ana yapı: ${esc(t.tr)}</h3><p>Aşağıdaki notlar ana yapıya aittir. Seçili alt parçanın özel açıklaması henüz hazırlanmadı.</p></div>`:''}<div class="detail-block"><h3>01 &nbsp; Konumu ve yapısı</h3><p>${esc(t.intro)}</p></div><div class="detail-block"><h3>02 &nbsp; Ne işe yarar?</h3><p>${esc(t.function)}</p></div><div class="detail-block clinical"><h3>03 &nbsp; Klinik bağlantı</h3><p>${esc(t.clinical||'Bu yapı için hastalık, neden ve etki açıklaması henüz uzman incelemesinden geçirilmedi. Bu sürümde anatomi ve temel işlev bilgisi sunuluyor.')}</p></div><div class="detail-block"><h3>Kaynak ve içerik durumu</h3><a href="${sourceURL(t)}" target="_blank" rel="noreferrer">OpenStax · İlgili anatomi bölümü ↗</a><p>Türkçe eğitim notu · Uzman incelemesi bekliyor.</p></div>`:`<div class="detail-block"><h3>Modeldeki yapı</h3><p>Bu yapı 3B atlasın bir parçasıdır. Özgün model adı yukarıda gösterilmiştir.</p></div><div class="detail-block clinical"><h3>Türkçe içerik hazırlanıyor</h3><p>Bu parçanın özel görevi, hastalıklarla ilişkisi ve neden–etki açıklaması henüz eklenmedi. Katmanları kullanarak komşuluklarını inceleyebilirsin.</p></div>`}`;
$('#focus').onclick=()=>frameObject(selected);$('#isolate').onclick=()=>{isolated=!isolated;refresh();};$('#hide').onclick=()=>{hidden.add(selected.userData.record.id);isolated=false;selected=null;refresh();$('#details').classList.remove('open');$('#selectionLabel').hidden=true;$('#detailContent').innerHTML='<div class="empty-symbol">◌</div><h2>Bir katman daha derine.</h2><p>Seçtiğin parça gizlendi. Arkasındaki yapıyı seçebilir veya ↺ düğmesiyle bütün parçaları geri getirebilirsin.</p>';};}
function matches(query){const words=normalize(query).trim().split(/\s+/).filter(Boolean);if(!words.length)return[];return catalog.filter(r=>words.every(w=>r.search.includes(w))).sort((a,b)=>{const an=normalize(displayName(a.name)),bn=normalize(displayName(b.name)),q=normalize(query);return Number(bn.startsWith(q))-Number(an.startsWith(q))||an.length-bn.length;});}
function search(){const q=$('#search').value.trim();const list=$('#searchResults');list.hidden=!q;if(!q)return;const found=matches(q);list.innerHTML=found.length?`<p>${found.length} eşleşme${found.length>60?' · İlk 60 sonuç':''}</p>`+found.slice(0,60).map(r=>`<button data-id="${r.id}">${esc(displayName(r.name))}<small>${esc(layerName(r.layer))}${topicFor(r.name)?' · Temel eğitim notu':''}</small></button>`).join(''):'<p>Yapı bulunamadı. Türkçe temel adı veya İngilizce anatomik adı deneyin.</p>';}
async function selectById(id){const r=catalog.find(r=>r.id===id);if(!r)throw Error('Yapı bulunamadı');await loadLayer(r.layer);const o=objects.get(id);if(!o)throw Error('3B parça bulunamadı');choose(o,{focus:true,isolate:true});return{id:r.id,name:displayName(r.name),layer:r.layer};}
function reset(back=false){isolated=false;hidden.clear();explosion=0;$('#explode').value=0;$('#explodeValue').textContent='%0';const target=new THREE.Vector3(0,.86,0);controls.target.copy(target);camera.position.set(back?-.05:.05,.91,back?-2.8:2.8);controls.update();$('#viewLabel').textContent=back?'ARKA':'ÖN';refresh();}
function wire(){renderLayers();$('#layers').onclick=e=>{const b=e.target.closest('[data-layer]');if(b)toggleLayer(b.dataset.layer);};$('#allLayers').onclick=async()=>{if(active.size===6){active.clear();isolated=false;renderLayers();refresh();return;}$('#allLayers').disabled=true;await Promise.all(layerDefs.filter(d=>!active.has(d.id)).map(d=>toggleLayer(d.id)));$('#allLayers').disabled=false;};$('#search').oninput=search;$('#search').onkeydown=e=>{if(e.key==='Enter'){$('#searchResults button')?.click();}if(e.key==='Escape'){$('#search').value='';search();}};$('#searchResults').onclick=async e=>{const b=e.target.closest('[data-id]');if(!b)return;b.disabled=true;try{await selectById(b.dataset.id);}catch(err){toast('Yapı yüklenemedi. Lütfen tekrar dene.');console.error(err);}b.disabled=false;};document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{$('#search').value=b.dataset.search;search();$('#search').focus();});$('#opacity').oninput=e=>{alpha=e.target.value/100;$('#opacityValue').value='%'+e.target.value;refresh();};$('#explode').oninput=e=>{explosion=e.target.value/100;$('#explodeValue').value='%'+e.target.value;refresh();};$('#reset').onclick=()=>reset();$('#front').onclick=()=>reset(false);$('#back').onclick=()=>reset(true);$('#zoomIn').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(.8).add(controls.target);controls.update();requestRender();};$('#zoomOut').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(1.25).add(controls.target);controls.update();requestRender();};$('#mobileLayers').onclick=()=>{$('#sidebar').classList.toggle('open');$('#details').classList.remove('open');};$('#closeDetail').onclick=()=>$('#details').classList.remove('open');$('#sourcesNav').onclick=()=>$('#sourceDialog').showModal();$('.dialog-close').onclick=()=>$('#sourceDialog').close();$('#atlasNav').onclick=()=>{reset();$('#sidebar').classList.remove('open');};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#sidebar').classList.add('open');$('#search').focus();}});}
async function init(){try{catalog=await fetch('./catalog.json').then(r=>{if(!r.ok)throw Error('Catalog');return r.json();});catalog.forEach(r=>r.search=searchText(r.name,r.layer));$('#totalCount').textContent=catalog.length.toLocaleString('tr-TR');scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(39,1,.005,25);renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;mount.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','Anatomi modeli. Döndürmek için sürükleyin, seçmek için dokunun. Klavye ile arama alanından yapı seçebilirsiniz.');const amb=new THREE.HemisphereLight(0xf4f1df,0x617473,2);scene.add(amb);const light=new THREE.DirectionalLight(0xffeed7,3.2);light.position.set(-2,3,4);scene.add(light);const fill=new THREE.DirectionalLight(0x9bc2c6,1.6);fill.position.set(2,1,-2);scene.add(fill);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=false;controls.minDistance=.08;controls.maxDistance=5;controls.target.set(0,.86,0);controls.addEventListener('change',requestRender);const resize=()=>{const {width,height}=mount.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();requestRender();};new ResizeObserver(resize).observe(mount);resize();reset();wire();let pointerStart;const raycaster=new THREE.Raycaster();renderer.domElement.addEventListener('pointerdown',e=>pointerStart={x:e.clientX,y:e.clientY,id:e.pointerId});renderer.domElement.addEventListener('pointerup',e=>{if(!pointerStart||pointerStart.id!==e.pointerId||Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>6)return;const rect=mount.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hits=raycaster.intersectObjects([...objects.values()].filter(o=>o.visible),false);if(hits.length)choose(hits[0].object);});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();toast('3B görüntü kesildi. Sayfayı yenileyerek tekrar yükleyebilirsin.');});$('#loadText').textContent='Kemik ve kas katmanları yükleniyor…';await Promise.all([loadLayer('skeleton'),loadLayer('muscular')]);ready=true;$('#loading').hidden=true;refresh();registerTools();}catch(e){console.error(e);$('#loading').innerHTML='<b>Atlas yüklenemedi</b><span>Bağlantını ve cihazının 3B desteğini kontrol et.</span><button id="retry" style="color:white;border:1px solid #82968a;padding:12px;border-radius:6px">Yeniden dene</button>';$('#retry').onclick=()=>location.reload();}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'search_anatomy',description:'Search the anatomy catalog by Turkish or English name.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(typeof input.query!=='string'||!input.query.trim())throw Error('query is required');return matches(input.query).slice(0,20).map(r=>({id:r.id,name:displayName(r.name),layer:r.layer}));}},{name:'select_anatomy_structure',description:'Select and focus a model structure and open its educational notes.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input.id!=='string')throw Error('id is required');return selectById(input.id);}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(console.warn);}catch(e){console.warn(e);}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
init();
